    (r"\beval\s*\(", "eval(...)"),
    (r"\bexec\s*\(", "exec(...)"),
    (r"pickle\.loads\s*\(", "pickle.loads(...)"),
    (r"subprocess\.[Pp]open\s*\(([^)]*shell\s*=\s*True)", "subprocess(..., shell=True)"),
    (r"os\.system\s*\(", "os.system(...)"),
]

TEXT_FILE_EXTS = {'.py', '.env', '.ini', '.cfg', '.txt', '.md', '.yaml', '.yml', '.json', '.sh'}


def walk_files(root: Path):
